const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Rectangle([74.9, 26.8, 75.5, 27.1]); // Bounding box for Lake Sambhar
  const date_2018 = {
    start: '2018-09-15',
    end: '2018-10-15'
  };
  const date_2019 = {
    start: '2019-04-01',
    end: '2019-04-30'
  };

  // Function to mask clouds in Sentinel-2 images
  const maskS2clouds = function(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale data
  };

  // Function to calculate MNDWI
  const addMNDWI = function(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI'); // Green - SWIR1
    return image.addBands(mndwi);
  };

  // 2. Data Acquisition & Check
  const collection_2018 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(lakeSambhar)
    .filterDate(date_2018.start, date_2018.end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

  const collection_2019 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(lakeSambhar)
    .filterDate(date_2019.start, date_2019.end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

  const count_2018 = collection_2018.size().getInfo();
  const count_2019 = collection_2019.size().getInfo();

  if (count_2018 === 0 || count_2019 === 0) {
    console.log(`Image count 2018: ${count_2018}`);
    console.log(`Image count 2019: ${count_2019}`);
    console.log("Empty collection for one or both periods.");
    console.log("C1");
    return;
  }
  console.log(`Image count 2018: ${count_2018}`);
  console.log(`Image count 2019: ${count_2019}`);

  // 3. Processing
  const image_2018 = collection_2018.map(maskS2clouds).map(addMNDWI).median().clip(lakeSambhar);
  const image_2019 = collection_2019.map(maskS2clouds).map(addMNDWI).median().clip(lakeSambhar);

  // A threshold to identify water based on MNDWI
  const mndwiThreshold = 0;
  const water_2018 = image_2018.select('MNDWI').gt(mndwiThreshold);
  const water_2019 = image_2019.select('MNDWI').gt(mndwiThreshold);

  // 4. Calculation & Validation
  const scale = 1000; // Use a coarse scale to avoid timeout but still get a representative count

  const waterPixels_2018_info = water_2018.selfMask().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: scale,
    maxPixels: 1e9
  }).get('MNDWI');

  const waterPixels_2019_info = water_2019.selfMask().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: scale,
    maxPixels: 1e9
  }).get('MNDWI');

  // Use evaluate to handle potential nulls safely
  const results = await new Promise((resolve, reject) => {
      ee.Dictionary({
          p2018: waterPixels_2018_info,
          p2019: waterPixels_2019_info
      }).evaluate(resolve, reject);
  });

  const waterPixels_2018 = results.p2018;
  const waterPixels_2019 = results.p2019;

  if (waterPixels_2018 === null || waterPixels_2019 === null) {
    console.log("Could not calculate pixel counts. Result is null.");
    console.log("C3");
    return;
  }

  if (waterPixels_2018 === 0 || waterPixels_2019 === 0) {
      console.log(`Water pixels 2018: ${waterPixels_2018}`);
      console.log(`Water pixels 2019: ${waterPixels_2019}`);
      console.log("No valid water pixels found after processing for at least one period.");
      console.log("C2");
      return;
  }

  // 5. Final Answer
  console.log(`Water pixels (approx area) in Sep 2018: ${waterPixels_2018}`);
  console.log(`Water pixels (approx area) in Apr 2019: ${waterPixels_2019}`);

  if (waterPixels_2019 < waterPixels_2018) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e}`);
    console.log("D");
  }
}

initEE();
